CREATE TABLE AccessoryProducts (AccessoryProductID INT(11) NOT NULL,AccessoryProductCode VARCHAR(10) NOT NULL UNIQUE,AccessoryProductName VARCHAR(255) NOT NULL,AccessoryDescription TEXT NOT NULL,AccessoryCategoryID INT(11) NOT NULL,AccessoryWholesalePrice DECIMAL(10,2) NOT NULL,AccessoryListPrice DECIMAL(10,2) NOT NULL,AccessorySize VARCHAR(255), DateCreated DATETIME NOT NULL,PRIMARY KEY ( AccessoryProductID ));








